import React, { useState } from "react";


export default function BookingForm() {
  const currentDate = new Date().toLocaleDateString();
  const minGuests = 1;
  const maxGuests = 10;

  const [resDate, setResDate] = useState(currentDate);
  const [resTime, setResTime] = useState("");
  const [guestCount, setGuestCount] = useState(minGuests);
  const [occasion, setOccasion] = useState("Birthday");

  const handleSubmit = (e) => {
    e.preventDefault();
  }

  return (
    <section className="reserve-table-background">
      <h1 className="title">Reserve table</h1>
      <form onSubmit={handleSubmit}>
        <div className="form-item">
          <label htmlFor="res-date">When are you visiting?</label>
          <input
            type="date"
            name="res-date"
            min={currentDate}
            value={resDate}
            onChange={(e) => setResDate(e.target.value)} />
        </div>
        <div className="form-item">
          <label htmlFor="res-time">Select the time</label>
          <input
            type="time"
            name="res-time"
            value={resTime}
            onChange={(e) => setResTime(e.target.value)} />
        </div>
         <div className="form-item">
          <label htmlFor="guest-count">Number of guest(s)</label>
          <input
            type="number"
            name="guest-count"
            min={ minGuests }
            max={ maxGuests }
            value={guestCount}
            onChange={(e) => setGuestCount(e.target.value)} />
        </div>
      </form>
    </section>
  )
}
